import type { GameDataSource } from './source';

/**
 * The game data shipped with the app (generated by `pnpm import:data`).
 * Loaded lazily so the 3+ MB JSON is a separate chunk and the UI shell can
 * render immediately.
 */
export function bundledDataSource(): GameDataSource {
  return {
    info: { id: 'bundled', label: 'Built-in data', kind: 'bundled' },
    load: async () => (await import('../../data/generated/game-data.json')).default
  };
}
